  memberDirectory: "<section class=\"inz-section inz-hero inz-hero--task inz-center\"><div class=\"inz-hero__plate par\" data-p=\"0.34\" data-scale=\"1.1\"></div><div class=\"inz-hero__scrim par\" data-p=\"0.14\"></div><div class=\"inz-hero__base\"></div>\n  <div class=\"inz-container\">\n    <h1>Member directory</h1>\n    <p class=\"inz-lede\">The directory of INZBC members is hosted on Member Jungle, the provisional system of record for membership.</p>\n    <div class=\"inz-actions inz-actions--center\">\n      <a href=\"https://inzbc.memberjungle.club\" class=\"inz-btn inz-btn--primary\">Open directory</a>\n    </div>\n  </div>\n</section>\n\n<section class=\"inz-section inz-section--paper\">\n  <div class=\"inz-container inz-prose\">\n    <h2>For members</h2>\n    <p>Log in to Member Jungle to update your profile, manage renewals and access member-only resources. The Wix site does not store membership data.</p>\n\n    <h2>Not a member yet?</h2>\n    <p>The directory is open to INZBC members. <a href=\"/membership/join\" onclick=\"inzNav(event, '/membership/join')\">Apply for membership</a>, or <a href=\"/membership\" onclick=\"inzNav(event, '/membership')\">read what membership includes</a> first.</p>\n  </div>\n</section>",
